int skb_copy_datagram_from_iovec(struct sk_buff *skb, const struct iovec *from, int offset, size_t count)
{
    size_t len = 0;
    int i;

    for (i = 0; i < count; i++) {
        len += from[i].iov_len;
    }

    if (len == 0)
        return -EFAULT;

    if (offset >= len)
        return 0;

    if (offset + skb->data_len > len)
        return -EFAULT;

    skb->len += len - offset;
    skb->data_len += len - offset;

    for (i = 0; i < count && offset < len; i++) {
        const struct iovec *iov = &from[i];
        size_t iov_len = iov->iov_len;
        char __user *iov_base = iov->iov_base;
        size_t copied = 0;

        if (offset < iov_len) {
            size_t copy_len = min(iov_len - offset, len - copied);

            if (copy_from_user(skb_put(skb, copy_len), iov_base + offset, copy_len))
                return -EFAULT;

            copied += copy_len;
            offset = 0;
        } else {
            offset -= iov_len;
            continue;
        }

        while (copied < iov_len) {
            size_t frag_len = min(iov_len - copied, (size_t)PAGE_SIZE);

            if (__get_user_pages(current, current->mm, (unsigned long)iov_base + copied, 1, 0, 0, &skb->frag_list, NULL))
                return -EFAULT;

            skb->frag_list = skb_shinfo(skb)->frags;
            skb->data_len += frag_len;
            copied += frag_len;
        }
    }

    return 0;
}

int iov_to_skb(struct sk_buff *skb, const struct iovec *from, int offset, size_t count) {
    const struct iovec *iov;
    int i;
    size_t len = 0;

    for (i = 0; i < count; i++) {
        iov = &from[i];
        len += iov->iov_len;
    }

    iov = from + offset;

    if (iov->iov_len) {
        size_t copy_len = min(skb->headroom, len);
        if (copy_data_from_user(skb->head, iov->iov_base, copy_len)) {
            return -EFAULT;
        }
        len -= copy_len;
        iov->iov_len -= copy_len;
        iov->iov_base += copy_len;
        if (!iov->iov_len)
            iov++;
    }

    while (len) {
        if (copy_len) {
            struct page *page = alloc_page(GFP_KERNEL);
            if (!page)
                return -ENOMEM;

            if (copy_highmem_page_from_user(page, iov->iov_base, len)) {
                __free_page(page);
                return -EFAULT;
            }

            skb_fill_page_desc(skb, skb_shinfo(skb)->nr_frags, page, 0, len);
            skb_shinfo(skb)->nr_frags++;
            iov->iov_len -= len;
            iov->iov_base += len;
        }
        len = 0;
    }

    return 0;
}

int skb_copy_datagram_from_iovec(struct sk_buff *skb, const struct iovec *from, int offset, size_t count)
{
    size_t len = 0;
    int i;
    const struct iovec *iov;

    for (i = 0; i < count; i++) {
        iov = &from[i];
        if (offset >= iov->iov_len) {
            offset -= iov->iov_len;
            continue;
        }

        len = iov->iov_len - offset;
        if (skb_tailroom(skb) < len) {
            return -EFAULT;
        }

        if (copy_from_user(skb->data + skb->tail, iov->iov_base + offset, len)) {
            return -EFAULT;
        }

        skb->tail += len;
        skb->len += len;
        offset = 0;
    }

    return 0;
}

int skb_copy_from_linear_data(struct sk_buff *skb, const struct iovec *from, int offset, size_t count)
{
    size_t len = 0;
    int i, ret = 0;
    const struct iovec *iov;

    for (i = 0; i < count; i++) {
        iov = &from[i];
        len += iov->iov_len;
    }

    if (len > skb->headroom + skb->len) {
        return -EFAULT;
    }

    for (i = 0; i < count; i++) {
        iov = &from[i];
        if (iov->iov_len == 0)
            continue;
        if (copy_from_user(skb->data + skb->len, iov->iov_base + offset, iov->iov_len)) {
            return -EFAULT;
        }
        skb->len += iov->iov_len;
        offset = 0;
    }

    return ret;
}

int skb_copy_datagram_from_iovec(struct sk_buff *skb, const struct iovec *from, int offset, size_t count)
{
    size_t len = 0;
    int i;

    for (i = 0; i < count; i++) {
        len += from[i].iov_len;
    }

    if (offset >= len)
        return 0;

    if (offset + skb->len > len)
        return -EFAULT;

    for (i = 0; i < count && offset > 0; i++) {
        size_t copy = from[i].iov_len;
        if (offset >= copy) {
            offset -= copy;
            continue;
        } else {
            break;
        }
    }

    for (; i < count && len > 0; i++) {
        size_t copy = from[i].iov_len - offset;
        if (copy > len)
            copy = len;

        if (skb->data_len == 0) {
            if (copy > skb_headroom(skb))
                return -EFAULT;
            skb_reserve(skb, copy);
            if (copy > skb_headroom(skb))
                return -EFAULT;
            if (copy_from_user(skb->data - copy, from[i].iov_base + offset, copy))
                return -EFAULT;
            skb->data -= copy;
            skb->len += copy;
        } else {
            struct page *page;
            unsigned int offset_in_page = offset_in_page(from[i].iov_base + offset);

            page = alloc_page(GFP_KERNEL);
            if (!page)
                return -ENOMEM;

            if (copy_from_user(page_address(page) + offset_in_page, from[i].iov_base + offset, copy)) {
                __free_page(page);
                return -EFAULT;
            }

            skb_add_page(skb, page, offset_in_page, copy);
        }

        len -= copy;
        offset = 0;
    }

    return 0;
}
